"""Patch tools/jb/shim_env_jb.js (generated by make_env_jb.py): winding-layout groundPoly, Panel texture size option, Card/Stamp/Tag/Counter
primitives, static tree scatter that avoids the stations, cinematic vignette."""
import pathlib
H = pathlib.Path(__file__).resolve().parent
p = H / 'shim_env_jb.js'; s = p.read_text(encoding='utf8')
def R(a, b, n=1):
    global s
    assert s.count(a) >= 1, a[:80]
    s = s.replace(a, b, n)

# 1. groundPoly must follow the layout offset
R("const P0 = mp(pts[0][0], y, pts[0][1]), c = STN.length ? STN[stIdx(pts[0][0])].c : 0, zo = P0[2] - pts[0][1];",
  "const P0 = mp(pts[0][0], y, pts[0][1]), c = STN.length ? STN[stIdx(pts[0][0])].c : 0, zo = P0[2] - pts[0][1], ox = P0[0] - pts[0][0] + c;")
R("pts.forEach((p, i) => i ? sh.lineTo(p[0] - c, -(p[1] + zo)) : sh.moveTo(p[0] - c, -(p[1] + zo)));", "pts.forEach((p, i) => i ? sh.lineTo(p[0] - c + ox, -(p[1] + zo)) : sh.moveTo(p[0] - c + ox, -(p[1] + zo)));")
R("new THREE.Vector3(p[0] - c, y + 0.05, p[1] + zo)", "new THREE.Vector3(p[0] - c + ox, y + 0.05, p[1] + zo)")
# 2. Panel texture size
R("const cw = 512, ch = Math.max(64, Math.min(1024, Math.round(512 * h / w)));", "const cw = o.cw || 512, ch = Math.max(64, Math.min(1024, Math.round(cw * h / w)));")

# 3. card primitives, inserted before Char()
cards = r"""
  // =========================================================================
  // CARDS: world-anchored documents, stamps, tags and counters painted into Panel textures (paper grain, spring entrance,
  // masked headline reveal, highlighter sweep, ink-stamp slam). Same call style as Label: all timing is a pure function of t.
  const PAPER = (() => { const c = document.createElement('canvas'); c.width = c.height = 96; const g = c.getContext('2d'), d = g.createImageData(96, 96); for (let i = 0; i < d.data.length; i += 4) { const v = 215 + hash(i * 7 + 3) * 40 | 0; d.data[i] = v; d.data[i + 1] = v - 5; d.data[i + 2] = v - 16; d.data[i + 3] = 46; } g.putImageData(d, 0, 0); return c; })();
  const springOut = u => { u = Math.max(0, Math.min(1, u)); return 1 + 2.2 * Math.pow(u - 1, 3) + 1.2 * Math.pow(u - 1, 2); };
  const FAM = ' system-ui, "Segoe UI", Arial, sans-serif', SERIF = 'Georgia, "Times New Roman", serif';
  function fitPx(g, text, weight, fam, maxW, px) { g.font = weight + ' ' + px + 'px' + fam; const w = g.measureText(text).width; return w > maxW ? Math.max(8, px * maxW / w) : px; }
  function rrect(g, x, y, w, h, r) { g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }
  // o: kind 'doc' | 'stamp' | 'tag' | 'counter'; t0 (appear), t1 (fade out, 0 = stay); doc: tag, head, lines[], hl (line index), dark;
  //    stamp/tag/counter: text, bg, fg, accent; counter: sub; rot (deg)
  function Card(x, y, z, w, h, o, t) {
    const t0 = o.t0 || 0, u = t - t0; if (u < 0) return; const t1 = o.t1 || 0, out = t1 ? 1 - Math.max(0, Math.min(1, (t - t1) / 0.35)) : 1; if (out <= 0.01) return;
    const kind = o.kind || 'tag', slam = kind === 'stamp', en = slam ? 1 + 0.9 * Math.pow(Math.max(0, 1 - u / 0.16), 2) : springOut(u / 0.45), sc = slam ? en : Math.max(0.05, en);
    const shake = slam && u < 0.3 ? Math.sin(u * 90) * 0.012 * (1 - u / 0.3) : 0, bob = kind === 'doc' ? Math.sin(u * 1.5) * 0.07 : 0, rot = ((o.rot !== undefined ? o.rot : slam ? -4 : 0) * Math.PI) / 180 + shake;
    const a = Math.min(1, u / (slam ? 0.08 : 0.15)) * out;
    const paint = (g, pw, ph) => {
      const m = pw * 0.035;
      if (kind === 'doc') {
        const dark = !!o.dark, bx = m, by = m, bw = pw - 2 * m, bh = ph - 2 * m;
        g.save(); g.shadowColor = 'rgba(11,25,30,0.38)'; g.shadowBlur = pw * 0.03; g.shadowOffsetX = pw * 0.008; g.shadowOffsetY = pw * 0.016; rrect(g, bx, by, bw, bh, pw * 0.016); g.fillStyle = dark ? '#16262D' : '#FAF7F0'; g.fill(); g.restore();
        rrect(g, bx, by, bw, bh, pw * 0.016); g.save(); g.clip(); g.fillStyle = g.createPattern(PAPER, 'repeat'); g.globalAlpha = dark ? 0.35 : 1; g.fillRect(bx, by, bw, bh); g.restore();
        g.lineWidth = pw * 0.004; g.strokeStyle = dark ? 'rgba(235,193,107,0.4)' : 'rgba(21,25,29,0.22)'; rrect(g, bx, by, bw, bh, pw * 0.016); g.stroke();
        const pad = bw * 0.06, X0 = bx + pad, tw = bw - 2 * pad, fs = bh * 0.1;
        if (o.tag) { g.font = '800 ' + fs * 0.62 + 'px' + FAM; const tgw = g.measureText(o.tag.toUpperCase()).width + fs * 0.9; g.fillStyle = o.accent || '#D11F2A'; rrect(g, X0, by + bh * 0.07, tgw, fs * 0.95, fs * 0.2); g.fill(); g.fillStyle = '#FAF7F0'; g.textAlign = 'left'; g.textBaseline = 'middle'; g.fillText(o.tag.toUpperCase(), X0 + fs * 0.45, by + bh * 0.07 + fs * 0.5); }
        g.strokeStyle = dark ? 'rgba(244,241,234,0.2)' : 'rgba(21,25,29,0.16)'; g.lineWidth = pw * 0.003; g.beginPath(); g.moveTo(X0, by + bh * 0.07 + fs * 1.25); g.lineTo(X0 + tw, by + bh * 0.07 + fs * 1.25); g.stroke();
        const hp = Math.max(0, Math.min(1, (u - 0.12) / 0.4)), hs = fitPx(g, o.head || '', '900', ' ' + SERIF.replace(/^/, ''), tw, fs * 1.55), hy = by + bh * 0.07 + fs * 2.6;
        g.save(); g.beginPath(); g.rect(X0 - 4, hy - hs, (tw + 8) * hp, hs * 1.4); g.clip(); g.fillStyle = dark ? '#F4F1EA' : '#15191D'; g.font = '900 ' + hs + 'px ' + SERIF; g.textAlign = 'left'; g.textBaseline = 'alphabetic'; g.fillText(o.head || '', X0, hy); g.restore();
        (o.lines || []).forEach((ln, i) => {
          const ly = hy + fs * 1.6 + i * fs * 1.45, la = Math.max(0, Math.min(1, (u - 0.3 - i * 0.12) / 0.3)), isH = i === o.hl, ps = fitPx(g, ln, isH ? '800' : '500', FAM, tw - 12, fs * 0.95);
          g.save(); g.globalAlpha = la; g.font = (isH ? '800 ' : '500 ') + ps + 'px' + FAM; const lw = g.measureText(ln).width;
          if (isH) { const hh = Math.max(0, Math.min(1, (u - (o.hlAt || 0.7)) / 0.35)), e = 1 - Math.pow(1 - hh, 3); g.fillStyle = dark ? 'rgba(217,155,38,0.5)' : 'rgba(255,214,10,0.72)'; rrect(g, X0 - 6, ly - ps * 0.95, (lw + 12) * e, ps * 1.25, ps * 0.2); g.fill(); }
          g.fillStyle = isH ? (dark ? '#FFF3D1' : '#0B191E') : (dark ? 'rgba(244,241,234,0.78)' : 'rgba(21,25,29,0.78)'); g.textAlign = 'left'; g.textBaseline = 'alphabetic'; g.fillText(ln, X0, ly); g.restore();
        });
      } else if (kind === 'stamp') {
        const col = o.bg || '#D94E43', bw = pw - 2 * m, bh = ph - 2 * m;
        g.save(); g.translate(pw / 2, ph / 2); g.fillStyle = 'rgba(255,255,255,0.0)';
        g.lineJoin = 'round'; g.strokeStyle = col; g.lineWidth = ph * 0.09; rrect(g, -bw / 2, -bh / 2, bw, bh, ph * 0.16); g.stroke(); g.lineWidth = ph * 0.03; rrect(g, -bw / 2 + ph * 0.13, -bh / 2 + ph * 0.13, bw - ph * 0.26, bh - ph * 0.26, ph * 0.08); g.stroke();
        g.fillStyle = col; g.textAlign = 'center'; g.textBaseline = 'middle'; const px = fitPx(g, o.text, '900', FAM, bw * 0.78, ph * 0.5); g.font = '900 ' + px + 'px' + FAM; g.fillText(o.text, 0, ph * 0.02);
        g.globalCompositeOperation = 'destination-out'; for (let i = 0; i < 260; i++) { g.globalAlpha = 0.55; g.fillRect((hash(i * 5 + 1) - 0.5) * bw, (hash(i * 7 + 2) - 0.5) * bh, 1 + hash(i * 3) * 5, 1 + hash(i * 11) * 3); } g.restore();
      } else if (kind === 'counter') {
        const bw = pw - 2 * m, bh = ph - 2 * m; g.save(); g.shadowColor = 'rgba(11,25,30,0.4)'; g.shadowBlur = pw * 0.03; g.shadowOffsetY = pw * 0.012; rrect(g, m, m, bw, bh, ph * 0.18); g.fillStyle = o.bg || '#0B1A22'; g.fill(); g.restore();
        g.lineWidth = ph * 0.035; g.strokeStyle = o.accent || '#E2B857'; rrect(g, m, m, bw, bh, ph * 0.18); g.stroke();
        g.fillStyle = o.fg || '#E2B857'; g.textAlign = 'center'; g.textBaseline = 'middle'; const hasSub = !!o.sub, px = fitPx(g, o.text, '900', ' ui-monospace, "Cascadia Mono", Consolas, monospace', bw * 0.86, ph * (hasSub ? 0.5 : 0.62)); g.font = '900 ' + px + 'px ui-monospace, "Cascadia Mono", Consolas, monospace'; g.fillText(o.text, pw / 2, ph * (hasSub ? 0.43 : 0.52));
        if (hasSub) { g.fillStyle = '#F4F1EA'; g.font = '700 ' + ph * 0.15 + 'px' + FAM; g.fillText(o.sub.toUpperCase(), pw / 2, ph * 0.8); }
      } else {   // tag: dark pill with an accent bar and a soft drop shadow
        const bw = pw - 2 * m, bh = ph - 2 * m, bg = o.bg || '#0B1A22', fg = o.fg || '#F4F1EA';
        g.save(); g.shadowColor = 'rgba(11,25,30,0.38)'; g.shadowBlur = pw * 0.025; g.shadowOffsetY = pw * 0.012; rrect(g, m, m, bw, bh, ph * 0.22); g.fillStyle = bg; g.fill(); g.restore();
        g.save(); rrect(g, m, m, bw, bh, ph * 0.22); g.clip(); g.fillStyle = o.accent || fg; g.fillRect(m, m, ph * 0.12, bh); g.restore();
        g.lineWidth = ph * 0.03; g.strokeStyle = 'rgba(255,255,255,0.18)'; rrect(g, m, m, bw, bh, ph * 0.22); g.stroke();
        g.fillStyle = fg; g.textAlign = 'center'; g.textBaseline = 'middle'; const px = fitPx(g, o.text, '900', FAM, bw * 0.8, ph * 0.5); g.font = '900 ' + px + 'px' + FAM; g.fillText(o.text, pw / 2 + ph * 0.05, ph * 0.52);
      }
    };
    Panel(x, y + bob, z, w, h, paint, { sx: sc, sy: sc, a, rot, cw: kind === 'doc' ? 1024 : 768 });
  }
"""
R("  function Char(role, x, z, hW, opts, t0, t1, t) {", cards + "  function Char(role, x, z, hW, opts, t0, t1, t) {")

# 4. trees: static scatter avoiding the stations
a = s.index("    { // roadside trees flanking"); b = s.index("    // ---- world layer: pooled meshes")
trees = """    { // trees scattered around the winding path, kept clear of every station (static: gives parallax as the camera travels)
      const N = 700, tr = new THREE.InstancedMesh(new THREE.ConeGeometry(2.3, 6.5, 7), new THREE.MeshStandardMaterial({ color: 0x4A8F66, roughness: 0.9 }), N), tk = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.35, 0.45, 2.4, 6), new THREE.MeshStandardMaterial({ color: 0x7A5B3F }), N), d = new THREE.Object3D();
      let n = 0;
      for (let i = 0; i < 4000 && n < N; i++) { const x = -150 + hash(i * 3 + 9) * 440, z = 110 - hash(i * 5 + 1) * 380, sc = 0.8 + hash(i * 11 + 2) * 0.9; let ok = true; for (let k = 0; k < LAYOUT.length; k++) { if (Math.hypot(x - LAYOUT[k][0], z - LAYOUT[k][1]) < 34) { ok = false; break; } } if (!ok) continue;
        d.position.set(x, 1.2 * sc + 3.25 * sc, z); d.scale.set(sc, sc, sc); d.updateMatrix(); tr.setMatrixAt(n, d.matrix); d.position.set(x, 1.2 * sc, z); d.updateMatrix(); tk.setMatrixAt(n, d.matrix); n++; }
      tr.count = n; tk.count = n; X.trees = tr; X.trunks = tk; scene.add(tr); scene.add(tk);
    }
"""
s = s[:a] + trees + s[b:]
R("\n    if (X.trees) { const ox = Math.round(camera.position.x / 90) * 90; X.trees.position.x = ox; X.trunks.position.x = ox; }", "")

# 5. vignette after the smear pass
R("    smearPass(t);\n    drawCast(t, CAST);", "    smearPass(t);\n    { const vg = ctx.createRadialGradient(960, 540, 420, 960, 540, 1180); vg.addColorStop(0, 'rgba(11,25,30,0)'); vg.addColorStop(1, 'rgba(11,25,30,0.24)'); ctx.save(); ctx.fillStyle = vg; ctx.fillRect(0, 0, 1920, 1080); ctx.restore(); }\n    drawCast(t, CAST);")
p.write_text(s, encoding='utf8'); print('env patched', len(s))

# build_jb: layout, camera file, aria-label
b = (H / 'build_jb.py').read_text(encoding='utf8')
b = b.replace("cam = open(T / 'shim_cam.js', encoding='utf8').read()", "cam = open(H / 'shim_cam_jb.js', encoding='utf8').read()")
b = b.replace(".replace('__DMIN__'", ".replace('__LAYOUT__', json.dumps(cfg.get('layout', [[0, -30 * k] for k in range(len(cfg['stn']))]))).replace('__DMIN__'")
b = b.replace("s = re.sub(r\"<title>.*?</title>\"", "s = re.sub(r'aria-label=\"Act 7[^\"]*\"', 'aria-label=\"%s\"' % cfg['title'].replace('\"', ''), s, count=1)\ns = re.sub(r\"<title>.*?</title>\"")
b = b.replace("env = open(H / 'shim_env_jb.js', encoding='utf8').read()", "env = open(H / 'shim_env_jb.js', encoding='utf8').read()")
(H / 'build_jb.py').write_text(b, encoding='utf8'); print('build patched')
